import json,random,subprocess,sys,os,tempfile
random.seed(5)
d=tempfile.mkdtemp()
def dec(n): return str(random.randint(1,999)/10**n)
tar={"currencies":{"EUR":{"cash":"0.05"},"CHF":{"cash":"whole"},"USD":{"cash":"none"},"X":{"cash":"0.5"}},"tariffs":{}}
for i in range(6):
    tar["tariffs"][f"t{i}"]={"currency":random.choice(["EUR","CHF","USD","X"]),"vat":random.choice(["0.21","0.055","0.125","0.2"]),"standing":dec(4),
     "bands":[{"upto":"100","price":dec(random.choice([2,3,4]))},{"upto":None,"price":dec(random.choice([3,4,5]))}]}
json.dump(tar,open(d+"/t.json","w"))
os.makedirs(d+"/acc")
for i in range(25):
    a={"account":f"A{i}","name":"n","tariff":f"t{random.randrange(6)}","period":{"start":"2026-03-01","end":"2026-03-31"},
     "readings":[{"meter":"M","kwh":str(random.choice([random.randint(0,2000)/random.choice([1,10,100,1000,8,40])]))}],
     "credits":[{"ref":"c","amount":random.choice([-4.25,0.005,1.005,2.675,-0.125,random.uniform(-9,9)])} for _ in range(random.randint(0,3))]}
    if random.random()<.5: a["standing"]=[{"from":"2026-03-01","to":"2026-03-10","rate":dec(5)},{"from":"2026-03-11","to":"2026-03-31","rate":dec(5)}]
    json.dump(a,open(f"{d}/acc/a{i}.json","w"))
cmds=[["tariffs"]]
for f in ("text","csv"): cmds.append(["batch",d+"/acc","--format",f])
for i in range(25):
    for f in ("text","csv","json"): 
        if i<8 or f!="x": cmds.append(["bill",f"{d}/acc/a{i}.json","--format",f])
for i in range(60):
    cmds.append(["quote",f"t{random.randrange(6)}",str(random.randint(0,3000)/random.choice([1,10,100,1000,8,40])),str(random.randint(1,100)),"--format",random.choice(["text","json"])])
bad=0
for c in cmds:
    out=[subprocess.run([sys.executable,"-m","meterbill","--tariffs",d+"/t.json",*c],cwd=r,capture_output=True) for r in("/tmp/orig","/app")]
    if (out[0].stdout,out[0].stderr,out[0].returncode)!=(out[1].stdout,out[1].stderr,out[1].returncode): bad+=1;print("DIFF",c)
print("bad",bad,len(cmds))
